#!/bin/bash -p
#SBATCH -A mt01 -p general -N1 --ntasks=1 -c 48 --mem=800G -t 04:00:00
#SBATCH --no-requeue
set -euo pipefail
umask 077
export PATH=/usr/local/bin:/usr/bin:/bin CUDA_VISIBLE_DEVICES='' PYTHONDONTWRITEBYTECODE=1
PY=$(command -v python3)
exec "$PY" -I -B - "$@" <<'P'
import base64,hashlib,json,sys,zlib
raw=zlib.decompress(base64.b64decode(''))
if hashlib.sha256(raw).hexdigest()!='90f968228b4130f5d65f33e3fce7604a582f8c80fd7b5bd56fd070625c647e47':raise ValueError('Embedded source differs')
authority=json.load(open(sys.argv[1]))
if authority['identity']!='774503e26f274a10c96ad06210d339c49ebc9a704ac254df81f389b0da4d98a1':raise ValueError('Configuration differs')
namespace={};exec(compile(raw,'p.py','exec'),namespace)
if len(sys.argv)==2:
    stage=None
elif len(sys.argv)==4 and sys.argv[2]=='--rehearsal':
    stage=sys.argv[3]
    if not stage:raise ValueError('Rehearsal staged root must be nonempty')
else:
    raise ValueError('Expected AUTHORITY [--rehearsal STAGED_ROOT]')
raise SystemExit(namespace['main'](authority, stage))
P
